sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

  if (current.u_luc_info_integracao.changes()) {
    gs.info('Campo u_luc_info_integracao atualizado. Continuação da ação permitida.');
    gs.addInfoMessage('Campo u_luc_info_integracao atualizado. Continuação da ação permitida.');
} else {
    current.setWorkflow(false);
    current.setAbortAction(true);
    gs.info('Ação abortada.');
    gs.addErrorMessage('Ação abortada: o campo "u_luc_info_integracao" não foi atualizado.');
    action.setRedirectURL(current);
}


})(current, previous);
